import pefile, re, struct

BASE = "artifacts/hard_pattern"
builds = ["layout_v1.exe","layout_v2.exe","layout_v3.exe"]

def to_pat(hexpat):
    out = bytearray()
    toks = hexpat.split()
    i = 0
    while i < len(toks):
        if toks[i] == "??":
            out.append(0); out.append(0xFF)  # marker scheme: value,nibble-mask? simpler below
            i += 1
        else:
            out.append(int(toks[i],16)); out.append(0x00)
            i += 1
    return out

def match(pat, data):
    # pat = list of (byte, is_wild)
    res = []
    n = len(pat)
    for i in range(len(data)-n+1):
        ok = True
        for j,(b,w) in enumerate(pat):
            if not w and data[i+j] != b:
                ok = False; break
        if ok: res.append(i)
    return res

opts = {
 "A": "8B 81 A8 02 00 00 35 ?? ?? ?? ?? ?? ?? ?? ?? ?? C1 C8 1D C3",
 "B": "8B 81 A8 02 00 00",
 "C": "8B 81 A8 02 00 00 35 19 7E 5C A3 05 03 2A 4F 17 C1 C8 1D C3",
 "D": "8B 81 A8 02 00 00 35 ?? ?? ?? ?? 05 ?? ?? ?? ?? C1 C8 1D C3",
}
pats = {k: [(int(t,16), t=="??") for t in v.split()] for k,v in opts.items()}

for b in builds:
    pe = pefile.PE(f"{BASE}/{b}")
    text = [s for s in pe.sections if b".text" in s.Name][0]
    data = text.get_data()
    print(b)
    for k,p in pats.items():
        m = match(p, data)
        print(f"  option {k}: {len(m)} match(es) at .text offsets {[hex(x) for x in m]} -> RVA {[hex(text.VirtualAddress+x) for x in m]}")

# strings in .rdata/.data for context
print("\n--- strings ---")
for b in builds:
    pe = pefile.PE(f"{BASE}/{b}")
    for sname in (b".rdata", b".data"):
        s = [x for x in pe.sections if sname in x.Name][0]
        d = s.get_data()
        for m in re.finditer(rb"[\x20-\x7e]{4,}", d):
            print(b, sname.decode(), hex(s.VirtualAddress+m.start()), m.group().decode())
